const input = $('Execute Workflow Trigger').first().json;
const userRaw = input.wpUser;
const passRaw = input.wpPassword;
const user = (Array.isArray(userRaw) ? userRaw[0] : userRaw || 'admonwp').toString().trim();
const passClean = (Array.isArray(passRaw) ? passRaw[0] : passRaw || '').toString().replace(/\s+/g, '').trim();

return [{
  json: {
    headerAuthRaw: `Basic ${Buffer.from(`${user}:${passClean}`, 'utf8').toString('base64')}`
  }
}];

const input = $input.first().json;

const normalizeText = (value) => value
  .toString()
  .replace(/\r?\n/g, ' ')
  .replace(/["'\[\]]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const trimWordsToLength = (text, maxLength) => {
  if (text.length <= maxLength) return text;

  const words = text.split(' ').filter(Boolean);
  let result = '';

  for (const word of words) {
    const candidate = result ? `${result} ${word}` : word;
    if (candidate.length > maxLength) break;
    result = candidate;
  }

  return result || text.slice(0, maxLength).trim();
};

const normalizeCategory = (value) => {
  const normalized = normalizeText(value);
  if (!normalized) return '';

  const primaryChunk = normalized.split(/[,:;|()]/)[0].trim();
  const compact = primaryChunk.replace(/\s+/g, ' ');

  // ⚠️ IMPORTANTE: eliminamos el .slice(0, 3) para no truncar cosas como "Análisis Predictivo"
  const shortValue = trimWordsToLength(compact, 32);

  return shortValue.length >= 3 ? shortValue : '';
};

const toArray = (value, formatter = normalizeText) => {
  if (Array.isArray(value)) return value.map(formatter).filter(Boolean);
  if (value === null || value === undefined) return [];

  const raw = value.toString().trim();
  if (!raw) return [];

  if (raw.startsWith('[') && raw.endsWith(']')) {
    try {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed.map(formatter).filter(Boolean);
    } catch {}
  }

  return raw.split(',').map(formatter).filter(Boolean);
};

const dedupe = (values) =>
  Array.from(new Map(values.map((value) => [value.toLowerCase(), value])).values());

// ===== TAGS (NO SE TOCA) =====
const rawTags = toArray(input.tags, normalizeText)
  .map((tag) => trimWordsToLength(tag, 60));

const tags = dedupe(rawTags).slice(0, 3);

// ===== CATEGORÍAS (CORREGIDO) =====
const rawCategoriesSource =
  input?.fields?.["Categorías"] ??
  input?.fields?.Categorías ??
  input?.["Categorías"] ??
  input?.categoryNames ??
  input?.categories ??
  '';

const explicitCategories = toArray(rawCategoriesSource, normalizeCategory).filter(Boolean);

// 👉 SOLO usamos la primera categoría de Airtable
const categoryNames = explicitCategories.length > 0
  ? [explicitCategories[0]]
  : ['General'];

return [{
  json: {
    ...input,
    categoryNames,
    tags
  }
}];

const item = $input.first().json;
const requested = (item.categoryNames ?? '').toString().trim();
const raw = item.data ?? item.body ?? item;

const normalize = (value) => value
  .toString()
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9\s-]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const normalizeSlug = (value) => normalize(value).replace(/\s+/g, '-');
const tokenize = (value) => normalize(value).split(' ').filter(Boolean);

function scoreCandidate(candidateName, candidateSlug, requestedName, requestedSlug) {
  if (!candidateName && !candidateSlug) return 0;
  if (candidateName === requestedName || candidateSlug === requestedSlug) return 100;

  let score = 0;
  if (candidateName.includes(requestedName) || requestedName.includes(candidateName)) score += 35;
  if (candidateSlug.includes(requestedSlug) || requestedSlug.includes(candidateSlug)) score += 35;

  const requestedTokens = tokenize(requestedName);
  const candidateTokens = new Set(tokenize(candidateName));
  const shared = requestedTokens.filter((token) => candidateTokens.has(token)).length;
  if (requestedTokens.length > 0) score += Math.round((shared / requestedTokens.length) * 40);

  return score;
}

let parsed = raw;
if (typeof raw === 'string') {
  try {
    parsed = JSON.parse(raw);
  } catch {
    parsed = [];
  }
}

const candidates = Array.isArray(parsed) ? parsed : parsed?.id ? [parsed] : [];
const requestedName = normalize(requested);
const requestedSlug = normalizeSlug(requested);
let bestMatch = null;
let bestScore = 0;

for (const candidate of candidates) {
  const candidateName = normalize(candidate?.name || '');
  const candidateSlug = normalize(candidate?.slug || '');
  const score = scoreCandidate(candidateName, candidateSlug, requestedName, requestedSlug);
  if (score > bestScore) {
    bestScore = score;
    bestMatch = candidate;
  }
}

if (bestMatch?.id && bestScore >= 45) {
  return [{ json: { id: bestMatch.id } }];
}

return [{ json: {} }];

const item = $input.first().json;

if (item.id) {
  return [{ json: { id: item.id } }];
}

if (item.code === 'term_exists') {
  const termId = item.data?.term_id || (Array.isArray(item.additional_data) && item.additional_data[0]);
  if (termId) return [{ json: { id: termId } }];
}

return [{ json: {} }];

